import { existsSync, mkdirSync, writeFileSync } from "node:fs"
import { dirname, resolve } from "node:path"
import { type Group, type TagKey, tagKeys, tags } from "../src/vocabulary/spec.ts"

/**
 * The Swift side of the vocabulary (C0): `Primitives/Registry.generated.swift`, a switch from each
 * `hz:*` tag to its view, regenerated by `ui:generate`; and one stub view per tag, written once
 * (`--stubs`), which its lane then owns. A lane never edits the registry.
 */

export const hazelUI = resolve(import.meta.dirname, "../../../apps/ios-hybrid/HazelUI/Sources/HazelUI")

const folders: { readonly [G in Group]: string } = {
	layout: "Layout",
	collections: "Collections",
	content: "Content",
	chat: "Chat",
	controls: "Controls",
	overlays: "Overlays",
	structure: "Structure",
	internal: "Layout",
}

/** `listDivider` to `HzListDivider`. */
export const viewName = (key: TagKey) => `Hz${key[0]!.toUpperCase()}${key.slice(1)}`

/** Where a tag's view lives, relative to `Sources/HazelUI`. */
export const viewPath = (key: TagKey) => {
	if (key === "ext") return `Extensions/${viewName(key)}.swift`
	if (key === "action") return `Primitives/Structure/${viewName(key)}.swift`
	return `Primitives/${folders[tags[key].group]}/${viewName(key)}.swift`
}

export const generateSwiftRegistry = (): string => {
	const cases = tagKeys
		.map((key) => `        case "hz:${key}": ${viewName(key)}(tree: tree, node: node)`)
		.join("\n")
	const lanes = tagKeys.map((key) => `        "hz:${key}": "${tags[key].ios}",`).join("\n")
	return `// Generated by \`bun run --cwd packages/ui ui:generate\` from \`packages/ui/src/vocabulary/spec.ts\`.
// Do not edit: each tag's view is its lane's own file (\`Primitives/<Group>/Hz<Tag>.swift\`).
import SwiftUI

public enum HazelVocabulary {
    /// Every \`hazel\` tag this build draws, with the lane that owns its view.
    public static let lanes: [String: String] = [
${lanes}
    ]
}

enum Primitives {
    @ViewBuilder @MainActor
    static func view(tree: Tree, node: Node) -> some View {
        switch node.tag {
${cases}
        default: ChildrenView(tree: tree, node: node)
        }
    }
}
`
}

const stub = (key: TagKey) => `import SwiftUI

// Owned by lane ${tags[key].ios} (\`docs/hazel-ui.md\`, "Phase 2: lanes"). C0 stub: the lane draws \`hz:${key}\` here
// from \`HazelTheme\` and its recipe; until then it is a \`NotImplementedView\`.
struct ${viewName(key)}: View {
    let tree: Tree
    let node: Node

    var body: some View { NotImplementedView(tag: node.tag, lane: "${tags[key].ios}") }
}
`

if (import.meta.main && process.argv.includes("--stubs")) {
	for (const key of tagKeys) {
		const path = resolve(hazelUI, viewPath(key))
		if (existsSync(path)) continue
		mkdirSync(dirname(path), { recursive: true })
		writeFileSync(path, stub(key))
		console.log(`stub ${viewPath(key)}`)
	}
}
